import dev from "@/data/arena-dev.json";
import test from "@/data/arena-test.json";
import type { Bundle, SuiteName, Task } from "./types";

/**
 * The dashboard is static: these bundles are generated by `verdict arena export`
 * and compiled in at build time. The deployed site needs no API key, database or
 * pipeline run - what a visitor sees is exactly what the runs recorded.
 */
const BUNDLES: Record<SuiteName, Bundle> = {
  test: test as unknown as Bundle,
  dev: dev as unknown as Bundle,
};

export const SUITES: SuiteName[] = ["test", "dev"];

export const SUITE_LABEL: Record<SuiteName, string> = {
  test: "held-out suite",
  dev: "development suite",
};

export function isSuite(value: string): value is SuiteName {
  return value === "test" || value === "dev";
}

export function getBundle(suite: SuiteName): Bundle {
  return BUNDLES[suite];
}

export function getTask(suite: SuiteName, taskId: string): Task | undefined {
  return BUNDLES[suite].tasks.find((t) => t.task_id === taskId);
}

/** `codex/gpt-6.1-sol` -> `gpt-6.1-sol`; `examiner/specify/codex/gpt-6.1-sol` -> `specify · gpt-6.1-sol`. */
export function shortName(name: string): string {
  const parts = name.split("/");
  const model = parts[parts.length - 1];
  if (parts[0] !== "examiner") return model;
  return parts.length > 3 ? `${parts[1]} · ${model}` : `examiner · ${model}`;
}

export function percent(value: number): string {
  return `${Math.round(value * 100)}%`;
}
